### Option 2: Script Console (Si le bookmarklet ne fonctionne pas)

1. Ouvrez [home.nest.com](https://home.nest.com) dans une **fenêtre de navigation privée** et connectez-vous
2. Appuyez sur `F12` → Cliquez sur l'onglet **Console**
3. Collez et exécutez ce script:

```javascript
(async function() {
  try {
    if (!window.location.hostname.includes('nest.com')) {
      alert('❌ Mauvais site web! Ce script doit être exécuté sur home.nest.com');
      return;
    }
    const entries = performance.getEntriesByType('resource');
    const issueTokenEntry = entries.find(e => e.name.includes('issueToken'));
    if (!issueTokenEntry) {
      alert('❌ Aucun issueToken trouvé. Veuillez:\n1. Actualiser la page (F5)\n2. Attendre qu\'elle soit complètement chargée\n3. Exécuter ce script à nouveau');
      return;
    }
    const issueToken = issueTokenEntry.name;
    const cookies = document.cookie;
    if (!issueToken.startsWith('https://accounts.google.com/o/oauth2/iframerpc')) {
      alert('❌ URL de jeton invalide');
      return;
    }
    if (!issueToken.includes('action=issueToken')) {
      alert('❌ URL de jeton invalide (action=issueToken manquante)');
      return;
    }
    if (!cookies || cookies.length < 100) {
      alert('❌ Cookies introuvables ou incomplets. Assurez-vous d\'être connecté.');
      return;
    }
    const requiredCookies = ['HSID=', 'SSID=', 'APISID=', 'SAPISID='];
    const missingCookies = requiredCookies.filter(c => !cookies.includes(c));
    if (missingCookies.length > 0) {
      alert('⚠️ Avertissement: Cookies manquants: ' + missingCookies.join(', ').replace(/=/g, ''));
    }
    console.log('\n========================================');
    console.log('✅ IDENTIFIANTS EXTRAITS AVEC SUCCÈS!');
    console.log('========================================\n');
    console.log('URL du jeton:\n' + issueToken + '\n');
    console.log('Cookies:\n' + cookies + '\n');
    console.log('========================================\n');
    const text = `URL du jeton:\n${issueToken}\n\nCookies:\n${cookies}`;
    try {
      await navigator.clipboard.writeText(text);
      alert('✅ Identifiants copiés dans le presse-papiers!\n\nCollez-les dans Home Assistant ci-dessous.');
    } catch (e) {
      alert('✅ Identifiants extraits!\n\nCopiez-les depuis la sortie de la console ci-dessus.');
    }
  } catch (error) {
    console.error('Erreur:', error);
    alert('❌ Une erreur s\'est produite: ' + error.message);
  }
})();
```

4. Copiez les identifiants et collez-les ci-dessous

